func (c *CreditGrantSpec) UnmarshalJSON(raw []byte) error {
	var value struct {
		Currency         string       `json:"currency"`
		Amount           Field[int64] `json:"amount"`
		FromPayment      bool         `json:"from_payment"`
		ExpiresAfterDays *int         `json:"expires_after_days"`
	}
