func (c *CustomerAmount) UnmarshalJSON(raw []byte) error {
	var value struct {
		MinAmount Field[int64] `json:"min_amount"`
		MaxAmount Field[int64] `json:"max_amount"`
	}
	d := json.NewDecoder(bytes.NewReader(raw))
	d.DisallowUnknownFields()
